  // how the bid goes, from the RfS (PDF pages)
  bidProcess: [
    { step: "Register on the ISN-ETS portal", detail: "Bids are made only on https://www.bharat-electronictender.com; register with M/s Electronic Tender.com and obtain a Class III digital signing certificate.",
      sources: [Q("rfs", 15, "Interested Bidders have to necessarily register themselves on the portal https://www.bharat-electronictender.com (“ETS portal”)")] },
    { step: "Download the official RfS from the portal", detail: "Only the portal's copy counts; amendments and clarifications appear there and prevail over the SECI website.",
      sources: [Q("rfs", 16, "It is mandatory to download official copy of the RfS Document from Electronic Tender System (ISN-ETS) Portal to participate in the RfS.")] },
    { step: "Pre-bid meeting and clarifications", detail: "Doubts go by email or through the portal; SECI answers at the pre-bid meeting and uploads the compiled answers; no clarification after the bid deadline; at least 7 days to bid after any amendment.",
      sources: [Q("rfs", 49, "A Pre-Bid Meeting shall be held as mentioned in the Bid Information Sheet")] },
    { step: "Pay the RfS cost and the bid processing fee", detail: "₹50,000 + GST and ₹20,000/MW + GST (at most ₹20 lakh), by NEFT/RTGS, receipts uploaded with the bid; MSEs with a UDYAM registration are exempt.",
      sources: [Q("rfs", 30, "Bids submitted without cost of the RfS document and/or Bid Processing Fee and/or Bank Guarantee/ Insurance Surety Bond against EMD (including partial submission of any one of the above amounts/ instruments), shall be summarily rejected.")] },
    { step: "Submit the bid: two envelopes online, the EMD offline", detail: "Techno-commercial envelope (Formats 7.1 to 7.10 and the attachments) and the financial envelope (7.11, 7.12, one tariff in the electronic form); the EMD bank guarantee or surety bond reaches SECI within 2 working days of the deadline.",
      sources: [Q("rfs", 45, "The Bidders will be required to submit the bank guarantee/surety bond, either in person or through post, at the office of SECI until the date as on 2 working days after the closing date of bid submission.")] },
    { step: "Techno-commercial evaluation (Step 1)", detail: "Opened after the EMD deadline; SECI checks eligibility and may ask for clarifications, to be answered within 7 days.",
      sources: [Q("rfs", 57, "Bid opening (online) will be done only after the deadline for submission of Bank Guarantee.")] },
    { step: "Financial bid opening and ranking (Step 2)", detail: "The first-round tariffs of the qualified bidders are ranked L1 upwards; equal tariffs share a rank; 80% of the bid capacity, at most 500 MW, is the capacity for award, and the highest bidder may be dropped.",
      sources: [Q("rfs", 57, "evaluations of Techno-Commercially Qualified Bids shall be done based on the “First Round Tariff”, quoted by the Bidder in the Electronic Form under Financial Bid on ISN-ETS bidding portal.")] },
    { step: "e-Reverse Auction (Step 3)", detail: "A week's notice by email, 30 minutes with 8-minute extensions, decrements of at least 1 paisa, capacity fixed, green / orange / red zones on screen.",
      sources: [Q("rfs", 58, "The reverse auction for the total tendered capacity shall be conducted on the portal https://www.bharat-electronictender.com, on the day as intimated by SECI to the eligible bidders.")] },
    { step: "Selection of the winners", detail: "Every bidder within L1 + 2% of the lowest tariff, in tariff order (ties by time stamp), up to the capacity for award; the last winner may get a part, never under 50 MW.",
      sources: [Q("rfs", 61, "The bidders who fall within the range of (and including) the lowest tariff (L1 tariff) + 2% of the L1 tariff-hereinafter referred to as “the range”- will be declared as Successful Bidders under the RfS")] },
    { step: "Letter of Award", detail: "One LoA per project, to the lead member for a consortium; SECI may cancel the process or reject high tariffs; the LoA lapses if SECI has not signed within 12 months.",
      sources: [Q("rfs", 63, "At the end of selection process, Letters of Award (LoAs) will be issued to the Successful Bidders for each Project.")] },
    { step: "PBG, Contract Administration Charges and documents within 20 days", detail: "The PBG (valid to 6 months after the SCD), ₹1 lakh/MW + GST, the shareholding certificate and the Annexure-F checklist; late: ₹1,000/MW a day.",
      sources: [Q("rfs", 38, "Successful Bidders will be required to submit the necessary documents, including Contract Administration Charges as per Clause 19 and PBG as per Clause 18 prior to signing of CfDA, within 20 days from issuance of LoA.")] },
    { step: "Sign the CfDA within 30 days", detail: "One agreement per project with SECI or your SPV; its Effective Date is the 30th day from the LoA; a completion schedule is submitted first and monthly progress reports follow.",
      sources: [Q("rfs", 37, "The CfDA will be signed within 30 days of issuance of Letter of Award (LoA) to the Successful Bidder.")] },
    { step: "Financial closure 6 months before the SCD", detail: "100% of the funds tied up, equipment orders placed, documents 14 days before the date; late: ₹100/MW a day in advance, else the PBG is encashed.",
      sources: [Q("rfs", 39, "The Projects shall achieve Financial Closure by the date as on 6 months prior to the SCD.")] },
    { step: "SCD: the battery supplies from month 15; own RE by month 36", detail: "Commission the battery and start full supply 15 months from the Effective Date (3 months' grace with the PBG at stake); commission your own solar or wind by 36 months; the term runs 15 years from the SCD.",
      sources: [Q("amd2", 2, "The Scheduled Commissioning Date (SCD) for commissioning of the full capacity of the ESS component of the Project shall be the date as on 15 months from the Effective Date of the CfDA")] },
  ],

