export const docById = Object.fromEntries(PACK.documents.map((d) => [d.id, d]));

/** The href of a quote: the PDF at its page, or null when the document is not provided. */
export function pageHref(quote) {
  const doc = docById[quote.doc];
  return doc?.file ? `${PACK.folder}${doc.file}#page=${quote.page}` : null;
}
